content.content:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --gold: #c8a96e;
  --gold-light: #dfc48e;
  --dark: #0c0c0c;
  --dark2: #141414;
  --dark3: #1e1e1e;
  --border: rgba(200,169,110,0.18);
  --text: #e2e2e2;
  --muted: #888;
  --r: 10px;
  --ease: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Noto Sans TC', 'PingFang TC', 'Microsoft JhengHei', sans-serif;
  background: var(--dark);
  color: var(--text);
  line-height: 1.75;
  font-size: 15px;
}

.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
.gold { color: var(--gold); }
.center { text-align: center; }
.mt-40 { margin-top: 40px; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
section { padding: 100px 0; }

/* 標籤 */
.tag {
  font-size: 18px;
  letter-spacing: 3px;
  color: var(--gold);
  margin-bottom: 14px;
  font-weight: 600;
  display: block;
}

/* 區段標題 */
.section-title {
  font-family: 'Noto Serif TC', serif;
  font-size: clamp(26px, 3.5vw, 40px);
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 52px;
}

/* 按鈕 */
.btn-gold {
  display: inline-block;
  background: var(--gold);
  color: #0c0c0c;
  padding: 14px 32px;
  border-radius: 4px;
  font-weight: 700;

