cat >> /tmp/bigtree_check/speakers-2026/style.css << 'CSSEOF'

/* ====== 教練金句（君子有所為有所不為）====== */
.coach-quote { background: var(--dark2); padding: 90px 0; text-align: center; }
.cq-text {
  font-family: 'Noto Serif TC', serif;
  font-size: clamp(22px, 2.6vw, 32px);
  font-weight: 700;
  color: var(--text);
  line-height: 1.7;
  max-width: 800px;
  margin: 0 auto;
}
.cq-sub { display: block; margin-top: 20px; font-size: 0.5em; color: var(--muted); font-weight: 400; letter-spacing: 1px; }

/* ====== 五個相信 / 五件事不做 ====== */
.belief-section { background: var(--dark); padding: 100px 0; }
.belief-section.alt { background: var(--dark2); }
.belief-grid { display: grid; gap: 26px; max-width: 760px; margin: 0 auto; }
.belief-item { display: flex; gap: 20px; align-items: flex-start; }
.belief-num {
  flex-shrink: 0; width: 46px; height: 46px; border-radius: 50%;
  background: var(--gold); color: #0c0c0c;
  display: grid; place-items: center;
  font-family: 'Noto Serif TC', serif; font-weight: 900; font-size: 18px;
}
.belief-num.alt { background: var(--dark3); color: var(--gold); border: 1px solid var(--border); }
.belief-item h4 { font-family: 'Noto Serif TC', serif; font-size: 18px; color: var(--gold); margin-bottom: 6px; }
.belief-item p { color: rgba(226,226,226,0.78); font-size: 14.5px; line-height: 1.8; }
CSSEOF
echo "CSS 補完"

